from research_helpers import Batch
b=Batch(2);add=b.add
for l,w in [('Malvi','ghar|ghare'),('Nimadi','ghar|ghār'),('Bagheli','gher|ghər')]:
 add(l,'house',w,'4428','Pali/Prakrit *ghara* and Hindi, Marwari, Gujarati and Marathi *ghar* directly match the house stem. Turner calls the deeper derivation from *gṛha* phonetically difficult; the proposal therefore stops at *ghara*.')
for l,w in [('Malvi','chapara|chappar|capar'),('Bagheli','cepera|cepper|cheppera|chepper')]:
 add(l,'roof',w,'4976','Compare Hindi *chappar/chaprā* ‘sloping thatch, hut’, Gujarati *chāprũ* ‘thatched roof’ and the article’s Punjabi *chappar*. The local vowels and optional written aspiration fit the same roof word under *chattvara*.')
for l,w in [('Malvi','kimāḍ|kamāḍ|kamaḍ|kimaḍə|kivaḍ|kũvāḍ'),('Bagheli','kemere|kemera|kemar|keuārə|kēura|kimeḍə|keuar|kēuar|kiuāḍ|kevaḍa|kivaḍa|kivaḍə')]:
 add(l,'door',w,'2963','CDIAL lists Hindi *kiwāṛ/kewāṛ*, Old Marwari *kibāṛi*, Gujarati *kamāṛ* and Marathi *kavāḍ*. These supply both the v/w and m variants and the retroflex stop/flap outcomes of *kavāṭa*.')
for l,w in [('Malvi','lakkaḍ|lakəḍa|lakədi|lakaḍa|lekaḍ|lakəḍi|lakaḍi|lākaḍā|lakiḍya|lakəda'),('Nimadi','lākəḍo|lakkaḍ|lākəḍi|lakəḍa|lākaḍā|lakəḍi|lākəḍā|lakkhuḍ|lākhəḍi'),('Bagheli','lekeḍi|lekeri|lekerin|lekeḍiya')]:
 add(l,'firewood',w,'10875-2','The retained velar belongs to CDIAL’s second branch: Prakrit *lakkuḍa*, Hindi *lakṛī* ‘firewood’, Gujarati *lākṛũ* and Marathi *lākuḍ*. The plain *lakuṭa* branch instead has weakened *laur/lauṛ-*; regional contact remains possible, especially in the eastern forms.','qualified',locator='10875.2')
for l,w in [('Malvi','ukhaḷa|ukhaḷo|ukkḷa|okhəli|okhḷi|okhəḷi|okhaḷi|okəḷi|ukaḷi|ukhaḷi|ukhəḷ'),('Nimadi','okhaḷə|ukkaḷ|ukhaḷi|ukəḷi|ukhāḷ|uklai|ukkhaḷ|okhaḍ|ukkhal|okhəlai|okhər'),('Bagheli','ukeli|ukeri|ukhali')]:
 add(l,'mortar',w,'2360-4','CDIAL’s fourth branch has Prakrit *ukkhala/okkhala*, Hindi *ūkhal/okhlī*, Gujarati/Marathi *ukhaḷ* and Bihari *okhar*. These match the contracted mortar forms, rather than the distinct uncontracted *ulūkhala* branches.',locator='2360.4')
for l,w in [('Malvi','musḷi|musaḷa|musəḷo|musaḷo|musaḷi|musaro|musli|musrā|musḷo|musḷa|musəḷa|musāḷ'),('Nimadi','mussaḷə|musaḷi|musāḷ|musaḷ|musalai'),('Bagheli','musel|muser|muserə|musər')]:
 add(l,'pestle',w,'10223','CDIAL’s s-branch gives Prakrit *musala*, Hindi *musal/mūslī*, Gujarati *musḷũ*, Marathi *musaḷ* and Bihari *mūsar*. The l/ḷ/r and contracted forms are directly comparable, with no inference to the separate retroflex-sibilant branch.',locator='10223.1')
add('Nimadi','pestle','muṣaḷə|muśaḷ','10223-2','CDIAL separately reconstructs *muṣala/*muśala* and cites Western Pahari *muśḷ* ‘pestle’. Nimadi’s explicitly written ṣ/ś selects that branch provisionally; confirm that the survey notation reflects a local contrast rather than transcription or learned influence.','qualified',locator='10223.2')
for l,w in [('Malvi','hatoḍi|hathoḍo|hathāḍi|hatoḍā|həthoḍi|atoḍi|hātoḍa'),('Nimadi','hathoḍi|hāthoḍo|hātthoḍi|hātoḍa|hateḍo|hāthoḍi|hathoḍai'),('Bagheli','hetheurin|hetheuḍi|hatheura|hatheuri|heṭheuḍi')]:
 add(l,'hammer',w,'14028','CDIAL’s *hastakūṭa* article gives Hindi *hathauṛā/-ṛī*, Gujarati *hathɔṛɔ/athɔṛɔ* and Marathi *hatoḍā/-ḍī*. These directly support both the au/o contraction and the h-less Malvi variant; the forms continue the lexicalised compound.')
for l,w in [('Malvi','kurāḍi|karāḍi|kulaḍi|karaḍi|kuraḍi|kulhāḍi|karāḍo'),('Nimadi','kuraḍi|kuraḍo|kurāḍi|kulhāḍi|kulāḍi|kulaḍa'),('Bagheli','khulheri|kulheri|kular|kulhaḍi|kulhar|kulhari')]:
 add(l,'axe',w,'3244','CDIAL connects Prakrit *kuhāḍa/-ḍī*, Hindi *kulhāṛī*, Bihari *kulhārī* and Marathi *kurhāḍī* with *kuṭhāra*. The r/l variants and rearranged aspiration are supported; regional variants with lost aspiration remain within this qualified family.','qualified')
for l,w in [('Malvi','suy|sui'),('Nimadi','suy|sui|sũy'),('Bagheli','suyi')]:
 add(l,'needle',w,'13551','Prakrit *sūī*, Hindi/Bihari *sūī*, Gujarati *soy* and Marathi *sūī* are explicitly in CDIAL’s first branch. The c-loss and resulting vowel sequence support these forms, separately from *suji* or nasalised c-retaining *sūñcī*.',locator='13551.1')
for l,w in [('Malvi','kapaḍo|kapaḍa|kapəḍā'),('Nimadi','kapəḍo|kapəḍa|kāpəḍo')]:
 add(l,'cloth',w,'2871','CDIAL has Prakrit *kappaḍa*, Marwari *kapṛo* and Marathi *kāpaḍ* beneath *karpaṭa*. The western forms fit this family; Turner flags borrowing for several neighbouring varieties, so immediate inheritance versus diffusion remains qualified.','qualified')
for l,w in [('Malvi','cānd|cand|cād'),('Nimadi','cānd'),('Bagheli','ceṇḍa|caṇḍ|caṇḍe')]:
 add(l,'moon',w,'4661','CDIAL’s moon sense gives Prakrit *caṃda*, Hindi/Gujarati *cā̃d*, Hindi *candā* and Bhojpuri *cān*. The reduced cluster and nasal/stop variants support the selected forms; longer *candrama* responses are not included.',locator='4661.2')
for l,w in [('Malvi','tāro|tārā|tara'),('Nimadi','tāro|tārā|tāre'),('Bagheli','ṭara|ṭərə|ṭerey|ṭereyyə')]:
 add(l,'star',w,'5798-4','CDIAL puts Hindi/Marathi *tārā* and Gujarati *tārɔ* specifically in its masculine *tāraka* branch, rather than feminine *tārā*. Bagheli’s retroflex initial and expanded endings need confirmation, so those remain qualified.','qualified' if l=='Bagheli' else 'straightforward',locator='5798.4')
for l,w in [('Malvi','pāni|pāṇi|paṇi'),('Nimadi','pāṇi|pāni'),('Bagheli','peni|paṇi')]:
 add(l,'water',w,'8082','Prakrit *pāṇia* and Hindi *pānī*, Marwari/Gujarati/Marathi *pāṇī* directly support the stem. Bagheli fronted *peni* is retained as a local vocalic variant; records merging rain with water are considered separately.')
b.save()
